CREATE FUNCTION public.qard_collect_atomic(_number text,_amount numeric,_cvv text,_key uuid,_terminal boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE me uuid:=auth.uid(); s public.qard_sub_qr; w public.qard_wallets; merchant public.qard_wallets; prior public.terminal_operations; expected text; next_balance numeric; current_balance numeric; minimum numeric; merchant_name text; legal_name text; result jsonb; hhmm time; limit_info record; BEGIN
 IF me IS NULL THEN RAISE EXCEPTION 'Inicia sesión'; END IF;
 IF _terminal AND NOT public.terminal_has_access(me,'collection') THEN RAISE EXCEPTION 'Terminal pendiente de autorización'; END IF;
 IF _key IS NULL OR _number !~ '^[0-9]{16}$' OR _cvv !~ '^[0-9]{4}$' OR _amount IS NULL OR _amount<=0 OR _amount<>round(_amount,2) OR _amount::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Número, monto o CVV dinámico inválidos'; END IF;
 IF public.cuenta_esta_bloqueada(me) THEN RAISE EXCEPTION 'Cuenta bloqueada'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(me::text||_key::text,2));
 SELECT * INTO prior FROM public.terminal_operations WHERE merchant_user_id=me AND request_key=_key;
 IF FOUND THEN IF prior.terminal_code<>'collection' OR prior.amount_mxn<>_amount OR prior.result->>'qard_number'<>_number THEN RAISE EXCEPTION 'Operación utilizada con otros datos'; END IF; RETURN prior.result; END IF;
 SELECT * INTO s FROM public.qard_sub_qr WHERE qard_number=_number;
 IF s.id IS NULL OR s.titular_user_id=me THEN RAISE EXCEPTION 'Tarjeta no disponible para este cobro'; END IF;
 IF public.cuenta_esta_bloqueada(s.titular_user_id) THEN RAISE EXCEPTION 'Tarjeta bloqueada'; END IF;
 PERFORM public.qard_ensure_wallet(me);
 PERFORM id FROM public.qard_wallets WHERE titular_user_id IN (me,s.titular_user_id) ORDER BY id FOR UPDATE;
 SELECT * INTO w FROM public.qard_wallets WHERE id=s.wallet_id;
 SELECT * INTO merchant FROM public.qard_wallets WHERE titular_user_id=me;
 SELECT * INTO s FROM public.qard_sub_qr WHERE id=s.id FOR UPDATE;
 IF s.estado<>'activa' OR w.estado<>'activa' OR merchant.estado<>'activa' THEN RAISE EXCEPTION 'Tarjeta o billetera apagada'; END IF;
 IF s.sub_index>0 AND NOT s.curp_verificada THEN RAISE EXCEPTION 'Activa la sub-QR con CURP'; END IF;
 expected:=public.qard_dec(CASE WHEN s.sub_index=0 THEN COALESCE(w.cvv_dinamico,s.cvv_dinamico) ELSE s.cvv_dinamico END);
 IF expected IS NULL OR expected<>_cvv THEN RAISE EXCEPTION 'CVV dinámico incorrecto o ya utilizado'; END IF;
 IF s.limite_por_transaccion IS NOT NULL AND _amount>s.limite_por_transaccion THEN RAISE EXCEPTION 'Excede el límite por transacción'; END IF;
 hhmm:=(now() AT TIME ZONE 'America/Hermosillo')::time;
 IF s.horario_inicio IS NOT NULL AND s.horario_fin IS NOT NULL AND ((s.horario_inicio<=s.horario_fin AND (hhmm<s.horario_inicio OR hhmm>s.horario_fin)) OR (s.horario_inicio>s.horario_fin AND hhmm>s.horario_fin AND hhmm<s.horario_inicio)) THEN RAISE EXCEPTION 'Fuera de horario permitido'; END IF;
 SELECT * INTO limit_info FROM public.qard_limite_cobros(me);
 IF limit_info.disponible IS NOT NULL AND _amount>limit_info.disponible THEN RAISE EXCEPTION 'Supera tu límite mensual de cobros'; END IF;
 current_balance:=CASE WHEN s.sub_index=0 THEN w.saldo_mxn ELSE s.saldo_mxn END;
 minimum:=CASE WHEN s.sub_index=0 THEN -50 ELSE 0 END;
 next_balance:=current_balance-_amount;
 IF next_balance<minimum THEN RAISE EXCEPTION 'Saldo insuficiente'; END IF;
 IF s.sub_index=0 THEN UPDATE public.qard_wallets SET saldo_mxn=next_balance,cvv_dinamico=public.qard_enc('') WHERE id=w.id; UPDATE public.qard_sub_qr SET cvv_dinamico=public.qard_enc('') WHERE id=s.id;
 ELSE UPDATE public.qard_sub_qr SET saldo_mxn=next_balance,cvv_dinamico=public.qard_enc('') WHERE id=s.id; END IF;
 UPDATE public.qard_wallets SET saldo_comercio_mxn=COALESCE(saldo_comercio_mxn,0)+_amount WHERE id=merchant.id RETURNING saldo_comercio_mxn INTO merchant.saldo_comercio_mxn;
 SELECT COALESCE(apodo,nombre,'Comercio') INTO merchant_name FROM public.profiles WHERE user_id=me;
 legal_name:=public.qard_nombre_legal(s.titular_user_id);
 INSERT INTO public.qard_movimientos(wallet_id,titular_user_id,sub_qr_id,tipo,monto_mxn,saldo_despues,comercio_user_id,comercio_nombre,descripcion,metadata) VALUES(w.id,s.titular_user_id,s.id,'cobro_comercio',_amount,next_balance,me,merchant_name,'Cobro en '||merchant_name,jsonb_build_object('terminal','collection','operation_key',_key,'comerciante_id',me,'cliente_id',s.titular_user_id,'sub_index',s.sub_index,'alias',s.alias,'lado','cargo','comision_comercio',0,'comision_plataforma',0));
 INSERT INTO public.qard_movimientos(wallet_id,titular_user_id,tipo,monto_mxn,saldo_despues,comercio_user_id,comercio_nombre,neto_comercio_mxn,descripcion,metadata) VALUES(merchant.id,me,'cobro_recibido',_amount,merchant.saldo_comercio_mxn,me,merchant_name,_amount,'Cobro recibido de '||COALESCE(legal_name,'cliente'),jsonb_build_object('terminal','collection','operation_key',_key,'comerciante_id',me,'cliente_id',s.titular_user_id,'lado','abono','bolsa','comercio'));
 result:=jsonb_build_object('ok',true,'qard_number',_number,'estado','cobrado','color','verde','mensaje','COBRADO $'||_amount,'saldo_despues',next_balance,'comision',0,'neto',_amount,'alias',s.alias,'sub_index',s.sub_index,'titular_nombre',legal_name);
 INSERT INTO public.terminal_operations(merchant_user_id,terminal_code,target_user_id,request_key,amount_mxn,result) VALUES(me,'collection',s.titular_user_id,_key,_amount,result);
 INSERT INTO public.messages(sender_id,receiver_id,message,is_read) VALUES('00000000-0000-0000-0000-000000000001',s.titular_user_id,format('QaRd: cobro de $%s en %s. Saldo: $%s. CVV dinámico utilizado.',_amount,merchant_name,next_balance),false);
 RETURN result; END; $$;
REVOKE ALL ON FUNCTION public.qard_collect_atomic(text,numeric,text,uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.qard_collect_atomic(text,numeric,text,uuid,boolean) TO authenticated;
COMMENT ON FUNCTION public.qard_collect_atomic(text,numeric,text,uuid,boolean) IS 'Intentional authenticated SECURITY DEFINER entry point: validates auth.uid, account locks, funds, dynamic CVV and optional agent permissions; writes financial records atomically. Never callable by anon.';
COMMENT ON FUNCTION public.terminal_reload(text,numeric,uuid) IS 'Intentional authenticated SECURITY DEFINER: only accepted, fully verified agents may debit their own funded wallet; atomic and idempotent.';
COMMENT ON FUNCTION public.terminal_submit_request(text,jsonb) IS 'Intentional authenticated entry point: immutable own pending application; requires owned uploaded documents and does not approve biometrics.';
COMMENT ON FUNCTION public.terminal_invite(uuid,text,boolean) IS 'Intentional authenticated entry point: requires both protected admin role and master consecutive number.';
COMMENT ON FUNCTION public.terminal_accept(uuid) IS 'Intentional authenticated entry point: only auth.uid may accept own pending invitation; cannot approve agent.';
COMMENT ON FUNCTION public.terminal_review_note(uuid,text) IS 'Intentional authenticated admin entry point: protected role and master check; notes cannot change approval or biometrics.';